// Package tavernpay implements TavernPay: recurring payment mandates on Gno.land.
//
// A payer locks an escrow of amount*maxPayments ugnot and names a payee.
// Anyone (a keeper) can execute a payment once it is due by block height;
// the realm pays `amount` ugnot from escrow to the payee. The payer can
// cancel at any time and get the remaining escrow refunded.
//
// Security notes (see gno AGENTS.md / gno-security-guide):
//   - Caller identity comes from cur.Previous(); no cur.IsCurrent() guard
//     (always true inside a crossing function).
//   - CreateMandate accepts payment via the -send envelope, so it requires
//     cur.Previous().IsUserCall() (NOT IsUser(), which also accepts
//     maketx-run ephemeral realms that could pre-consume the envelope),
//     paired with runtime.AssertOriginCall().
//   - State is mutated before any coin movement (CEI).
//   - Render never echoes user-controlled strings: the only inputs are
//     typed addresses (bech32, safe charset) and integers.
package tavernpay

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
)

// Mandate is one recurring payment agreement.
type Mandate struct {
	ID             int64
	Payer          address
	Payee          address
	Amount         int64 // ugnot per payment
	IntervalBlocks int64 // blocks between payments
	MaxPayments    int64
	PaymentsMade   int64
	NextDueHeight  int64
	Escrow         int64 // ugnot still locked
	Active         bool
}

var (
	mandates []Mandate
	nextID   int64 = 1
)

// CreateMandate opens a mandate. The caller must attach exactly
// amount*maxPayments ugnot via -send; the coins become the escrow.
// Returns the mandate ID.
func CreateMandate(cur realm, payee address, amount, intervalBlocks, maxPayments int64) int64 {
	if !cur.Previous().IsUserCall() {
		panic("CreateMandate: only a direct user call can open a mandate")
	}
	runtime.AssertOriginCall()
	deposit := unsafe.OriginSend().AmountOf("ugnot")
	return createMandate(cur.Previous().Address(), payee, amount, intervalBlocks, maxPayments, deposit)
}

// ExecuteMandate pays one due installment to the payee. Anyone may call
// it (keeper model): the realm itself enforces due-ness, so no trusted
// scheduler is needed.
func ExecuteMandate(cur realm, id int64) {
	idx := findMandateIndex(id)
	if idx < 0 {
		panic("ExecuteMandate: unknown mandate")
	}
	applyPayment(idx, runtime.ChainHeight())
	m := mandates[idx]
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), m.Payee, chain.Coins{{Denom: "ugnot", Amount: m.Amount}})
}

// CancelMandate closes a mandate and refunds the remaining escrow to the
// payer. Only the payer can cancel.
func CancelMandate(cur realm, id int64) {
	if !cur.Previous().IsUserCall() {
		panic("CancelMandate: only a direct user call can cancel a mandate")
	}
	idx := findMandateIndex(id)
	if idx < 0 {
		panic("CancelMandate: unknown mandate")
	}
	refund := applyCancel(idx, cur.Previous().Address())
	if refund > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), mandates[idx].Payer, chain.Coins{{Denom: "ugnot", Amount: refund}})
	}
}

// GetMandate returns a copy of one mandate by ID.
func GetMandate(id int64) Mandate {
	idx := findMandateIndex(id)
	if idx < 0 {
		panic("GetMandate: unknown mandate")
	}
	return mandates[idx]
}

// ListMandates returns a copy of all mandates, newest last.
func ListMandates() []Mandate {
	out := make([]Mandate, len(mandates))
	copy(out, mandates)
	return out
}

// MandateCount returns how many mandates exist.
func MandateCount() int64 {
	return int64(len(mandates))
}

// RealmBalance returns the realm's current ugnot balance.
func RealmBalance() int64 {
	return banker.NewReadonlyBanker().GetCoin(unsafe.CurrentRealm().Address(), "ugnot")
}

// Render shows a Markdown dashboard of all mandates.
func Render(path string) string {
	out := "# TavernPay — recurring payment mandates\n\n"
	out += "Pay once, get paid on schedule. A payer locks amount x maxPayments ugnot; "
	out += "any keeper can execute a due installment; the payer can cancel anytime for a refund.\n\n"
	out += "Realm balance: " + strconv.FormatInt(RealmBalance(), 10) + " ugnot\n\n"
	if len(mandates) == 0 {
		out += "_No mandates yet._\n"
		return out
	}
	out += "| ID | Payer | Payee | Amount | Paid | Next due (height) | Escrow | Active |\n"
	out += "|---:|---|---|---:|---:|---:|---:|:---:|\n"
	for _, m := range mandates {
		out += "|" + strconv.FormatInt(m.ID, 10)
		out += "|" + m.Payer.String()
		out += "|" + m.Payee.String()
		out += "|" + strconv.FormatInt(m.Amount, 10)
		out += "|" + strconv.FormatInt(m.PaymentsMade, 10) + "/" + strconv.FormatInt(m.MaxPayments, 10)
		out += "|" + strconv.FormatInt(m.NextDueHeight, 10)
		out += "|" + strconv.FormatInt(m.Escrow, 10)
		if m.Active {
			out += "|yes|\n"
		} else {
			out += "|no|\n"
		}
	}
	return out
}

// createMandate validates inputs and appends a mandate. Pure state logic
// (no coin movement); the crossing wrapper verifies the deposit.
func createMandate(payer, payee address, amount, intervalBlocks, maxPayments, deposit int64) int64 {
	if amount <= 0 {
		panic("CreateMandate: amount must be positive")
	}
	if intervalBlocks <= 0 {
		panic("CreateMandate: intervalBlocks must be positive")
	}
	if maxPayments <= 0 {
		panic("CreateMandate: maxPayments must be positive")
	}
	if deposit != amount*maxPayments {
		panic("CreateMandate: attached ugnot must equal amount*maxPayments")
	}
	m := Mandate{
		ID:             nextID,
		Payer:          payer,
		Payee:          payee,
		Amount:         amount,
		IntervalBlocks: intervalBlocks,
		MaxPayments:    maxPayments,
		PaymentsMade:   0,
		NextDueHeight:  runtime.ChainHeight() + intervalBlocks,
		Escrow:         deposit,
		Active:         true,
	}
	mandates = append(mandates, m)
	nextID++
	return m.ID
}

// applyPayment advances one installment's state. Panics unless the
// mandate is active, incomplete, and due at the given height.
func applyPayment(idx int, height int64) {
	m := &mandates[idx]
	if !m.Active {
		panic("ExecuteMandate: mandate not active")
	}
	if m.PaymentsMade >= m.MaxPayments {
		panic("ExecuteMandate: mandate complete")
	}
	if height < m.NextDueHeight {
		panic("ExecuteMandate: payment not due yet")
	}
	m.PaymentsMade++
	m.Escrow -= m.Amount
	m.NextDueHeight += m.IntervalBlocks
	if m.PaymentsMade >= m.MaxPayments {
		m.Active = false
	}
}

// applyCancel closes a mandate and returns the refundable escrow.
// Panics unless the caller is the payer and the mandate is active.
func applyCancel(idx int, caller address) int64 {
	m := &mandates[idx]
	if !m.Active {
		panic("CancelMandate: mandate not active")
	}
	if caller != m.Payer {
		panic("CancelMandate: only the payer can cancel")
	}
	refund := m.Escrow
	m.Escrow = 0
	m.Active = false
	return refund
}

// findMandateIndex returns the slice index of a mandate, or -1.
func findMandateIndex(id int64) int {
	for i := range mandates {
		if mandates[i].ID == id {
			return i
		}
	}
	return -1
}

package tavernpay

import "testing"

var (
	testPayer = address("g1h2fd0ykqkfgh6heggn6uh0r9qnxz9ujpka5fce")
	testPayee = address("g1jg8mtutu9khhfwc07hx9gu5w5j9z5hfnw4z6q")
)

func resetState() {
	mandates = nil
	nextID = 1
}

func expectPanic(t *testing.T, name string, fn func()) {
	defer func() {
		if r := recover(); r == nil {
			t.Fatalf("%s: expected panic, got none", name)
		}
	}()
	fn()
}

func TestCreateMandate(cur realm, t *testing.T) {
	resetState()
	id := createMandate(testPayer, testPayee, 100, 10, 3, 300)
	if id != 1 {
		t.Fatalf("expected id 1, got %d", id)
	}
	m := GetMandate(1)
	if m.Amount != 100 || m.Escrow != 300 || m.MaxPayments != 3 {
		t.Fatalf("bad mandate state: %v", m)
	}
	if !m.Active {
		t.Fatalf("mandate should be active")
	}
	if m.Payer != testPayer || m.Payee != testPayee {
		t.Fatalf("bad parties: payer %s payee %s", m.Payer.String(), m.Payee.String())
	}
	if MandateCount() != 1 {
		t.Fatalf("expected count 1, got %d", MandateCount())
	}
}

func TestCreateMandateBadInputs(cur realm, t *testing.T) {
	resetState()
	expectPanic(t, "zero amount", func() {
		createMandate(testPayer, testPayee, 0, 10, 3, 0)
	})
	expectPanic(t, "zero interval", func() {
		createMandate(testPayer, testPayee, 100, 0, 3, 300)
	})
	expectPanic(t, "zero maxPayments", func() {
		createMandate(testPayer, testPayee, 100, 10, 0, 0)
	})
	expectPanic(t, "wrong deposit", func() {
		createMandate(testPayer, testPayee, 100, 10, 3, 299)
	})
	expectPanic(t, "over deposit", func() {
		createMandate(testPayer, testPayee, 100, 10, 3, 301)
	})
}

func TestApplyPaymentFlow(cur realm, t *testing.T) {
	resetState()
	id := createMandate(testPayer, testPayee, 100, 10, 3, 300)
	due := GetMandate(id).NextDueHeight
	// Too early: must panic.
	expectPanic(t, "pay before due", func() {
		applyPayment(0, due-1)
	})
	// First payment at due height.
	applyPayment(0, due)
	m := GetMandate(id)
	if m.PaymentsMade != 1 || m.Escrow != 200 || !m.Active {
		t.Fatalf("after pay 1: %v", m)
	}
	// Second payment one interval later.
	applyPayment(0, due+10)
	m = GetMandate(id)
	if m.PaymentsMade != 2 || m.Escrow != 100 || !m.Active {
		t.Fatalf("after pay 2: %v", m)
	}
	// Third payment completes the mandate.
	applyPayment(0, due+20)
	m = GetMandate(id)
	if m.PaymentsMade != 3 || m.Escrow != 0 || m.Active {
		t.Fatalf("after pay 3: %v", m)
	}
	// Fourth payment must panic.
	expectPanic(t, "pay after complete", func() {
		applyPayment(0, due+30)
	})
}

func TestApplyCancel(cur realm, t *testing.T) {
	resetState()
	id := createMandate(testPayer, testPayee, 100, 10, 3, 300)
	applyPayment(0, GetMandate(id).NextDueHeight)
	// Non-payer cannot cancel.
	expectPanic(t, "cancel by non-payer", func() {
		applyCancel(0, testPayee)
	})
	// Payer cancels: refund is the remaining escrow (200).
	refund := applyCancel(0, testPayer)
	if refund != 200 {
		t.Fatalf("expected refund 200, got %d", refund)
	}
	m := GetMandate(id)
	if m.Active || m.Escrow != 0 {
		t.Fatalf("after cancel: %v", m)
	}
	// Cancelling again must panic.
	expectPanic(t, "cancel twice", func() {
		applyCancel(0, testPayer)
	})
}

func TestListMandates(cur realm, t *testing.T) {
	resetState()
	createMandate(testPayer, testPayee, 100, 10, 2, 200)
	createMandate(testPayer, testPayee, 50, 5, 4, 200)
	list := ListMandates()
	if len(list) != 2 {
		t.Fatalf("expected 2 mandates, got %d", len(list))
	}
	if list[0].ID != 1 || list[1].ID != 2 {
		t.Fatalf("bad ids: %d, %d", list[0].ID, list[1].ID)
	}
	// Mutating the returned slice must not touch realm state.
	list[0].Amount = 999
	if GetMandate(1).Amount != 100 {
		t.Fatalf("ListMandates leaked mutable state")
	}
}

func TestRender(cur realm, t *testing.T) {
	resetState()
	out := Render("")
	if out == "" {
		t.Fatalf("empty render")
	}
	createMandate(testPayer, testPayee, 100, 10, 2, 200)
	out = Render("")
	if !contains(out, "TavernPay") || !contains(out, "100") {
		t.Fatalf("render missing content: %s", out)
	}
}

func contains(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

package reviewqueue

import (
 "strconv"
 "strings"
)

type Workspace struct { ID int; Name string; Purpose string; Chair address }
type Review struct { Reviewer address; Verdict string; Reason string; Round int }
type Event struct { Sequence int; Actor address; Action string; Detail string; Round int }
type Proposal struct {
 ID int; WorkspaceID int; Author address; Title string; Summary string; Category string
 Status string; Round int; Reviewers []address; Reviews []Review; History []Event
}
var spaces []Workspace
var proposals []Proposal

func text(s string, max int) string {
 s = strings.TrimSpace(s)
 if len(s) == 0 || len(s) > max { panic("text is empty or exceeds limit") }
 for _, ch := range s { if ch < 32 && ch != '\n' && ch != '\t' { panic("control characters are not allowed") } }
 return s
}
func space(id int) *Workspace { if id < 1 || id > len(spaces) { panic("workspace not found") }; return &spaces[id-1] }
func proposal(id int) *Proposal { if id < 1 || id > len(proposals) { panic("proposal not found") }; return &proposals[id-1] }
func record(p *Proposal, actor address, action, detail string) {
 p.History = append(p.History, Event{len(p.History)+1,actor,action,detail,p.Round})
}
func CreateWorkspace(cur realm, name, purpose string) int {
 name = text(name,80); purpose = text(purpose,500)
 if len(spaces) >= 1000 { panic("workspace capacity reached") }
 id := len(spaces)+1
 spaces = append(spaces, Workspace{id,name,purpose,cur.Previous().Address()})
 return id
}
func Submit(cur realm, workspaceID int, title, summary, category string) int {
 space(workspaceID)
 title=text(title,120); summary=text(summary,3000); category=text(category,40)
 if len(proposals) >= 10000 { panic("proposal capacity reached") }
 id:=len(proposals)+1; actor:=cur.Previous().Address()
 p:=Proposal{ID:id,WorkspaceID:workspaceID,Author:actor,Title:title,Summary:summary,Category:category,Status:"submitted",Round:1}
 record(&p,actor,"submitted",title)
 proposals=append(proposals,p)
 return id
}
func AssignReviewers(cur realm, id int, first, second address) {
 p:=proposal(id); actor:=cur.Previous().Address()
 if actor != space(p.WorkspaceID).Chair { panic("only workspace chair may assign") }
 if p.Status != "submitted" { panic("proposal is not awaiting assignment") }
 if first == second || first == p.Author || second == p.Author { panic("two distinct non-author reviewers required") }
 // Address values must be valid bech32 addresses, not arbitrary strings.
 if !first.IsValid() || !second.IsValid() { panic("invalid reviewer address") }
 p.Reviewers=[]address{first,second}; p.Status="reviewing"
 record(p,actor,"reviewers assigned",string(first)+", "+string(second))
}
func SubmitReview(cur realm, id int, verdict, reason string) {
 p:=proposal(id); actor:=cur.Previous().Address()
 if p.Status != "reviewing" { panic("proposal is not in review") }
 if actor != p.Reviewers[0] && actor != p.Reviewers[1] { panic("only an assigned reviewer may review") }
 if verdict != "approve" && verdict != "changes" && verdict != "reject" { panic("invalid verdict") }
 reason=text(reason,1000)
 for _, r:=range p.Reviews { if r.Round==p.Round && r.Reviewer==actor { panic("one review per reviewer per round") } }
 p.Reviews=append(p.Reviews,Review{actor,verdict,reason,p.Round})
 record(p,actor,"review submitted",verdict+": "+reason)
}
func Finalize(cur realm, id int) {
 p:=proposal(id); actor:=cur.Previous().Address()
 if actor != space(p.WorkspaceID).Chair { panic("only workspace chair may finalize") }
 if p.Status != "reviewing" { panic("proposal is not in review") }
 count:=0; approves:=0; rejects:=0
 for _, r:=range p.Reviews { if r.Round==p.Round { count++; if r.Verdict=="approve" { approves++ }; if r.Verdict=="reject" { rejects++ } } }
 if count!=2 { panic("two reviews required before finalizing") }
 p.Status="changes"
 if approves==2 { p.Status="approved" }; if rejects==2 { p.Status="rejected" }
 record(p,actor,"decision finalized",p.Status)
}
func Revise(cur realm, id int, summary string) {
 p:=proposal(id); actor:=cur.Previous().Address()
 if actor!=p.Author { panic("only author may revise") }
 if p.Status!="changes" { panic("proposal is not awaiting changes") }
 summary=text(summary,3000)
 p.Summary=summary; p.Round++; p.Reviewers=nil; p.Status="submitted"
 record(p,actor,"revision submitted",summary)
}
func Withdraw(cur realm, id int) {
 p:=proposal(id); actor:=cur.Previous().Address()
 if actor!=p.Author { panic("only author may withdraw") }
 if p.Status!="submitted" && p.Status!="changes" { panic("cannot withdraw during or after review") }
 p.Status="withdrawn"; record(p,actor,"withdrawn","")
}
func Snapshot() string {
 out := "{\"workspaces\":["
 for i,s:=range spaces {
  if i>0 { out+="," }
  out+="{\"id\":"+strconv.Itoa(s.ID)+",\"name\":"+strconv.Quote(s.Name)+",\"chair\":"+strconv.Quote(string(s.Chair))+"}"
 }
 out+="],\"proposals\":["
 for i,p:=range proposals {
  if i>0 { out+="," }
  out+="{\"id\":"+strconv.Itoa(p.ID)+",\"title\":"+strconv.Quote(p.Title)+",\"summary\":"+strconv.Quote(p.Summary)+",\"status\":"+strconv.Quote(p.Status)+",\"round\":"+strconv.Itoa(p.Round)+"}"
 }
 return out+"]}"
}
func safe(s string) string {
 s=strings.ReplaceAll(s,"&","&amp;")
 s=strings.ReplaceAll(s,"<","&lt;"); s=strings.ReplaceAll(s,">","&gt;")
 for _, x:=range []string{"\\","*","_","[","]","#","`","|"} { s=strings.ReplaceAll(s,x,"\\"+x) }
 return s
}
func Render(path string) string {
 out:="# ReviewQueue\n\nShared proposals. Reasoned decisions. A public record.\n\n**Unaudited prototype. All content is public. No funds, token voting, identity verification, or proof of review quality.**\n\n"
 if strings.HasPrefix(path,"proposal/") {
  id,err:=strconv.Atoi(strings.TrimPrefix(path,"proposal/")); if err!=nil || id<1 || id>len(proposals) { return out+"Proposal not found." }
  p:=proposal(id); out+="## "+safe(p.Title)+"\n\n**"+p.Status+" · Round "+strconv.Itoa(p.Round)+"**\n\n"+safe(p.Summary)+"\n\n### Public history\n\n"
  for _,e:=range p.History { out+="- "+strconv.Itoa(e.Sequence)+" · "+safe(e.Action)+" · "+safe(string(e.Actor))+"\n\n  "+safe(e.Detail)+"\n" }
  return out
 }
 out+="## Workspaces\n\n"
 for _,s:=range spaces { out+="- **"+strconv.Itoa(s.ID)+" · "+safe(s.Name)+"** — "+safe(s.Purpose)+"\n" }
 out+="\n## Proposals\n\n"
 for i:=len(proposals)-1;i>=0;i-- { p:=proposals[i]; out+="- [#"+strconv.Itoa(p.ID)+" "+safe(p.Title)+"](:proposal/"+strconv.Itoa(p.ID)+") · "+p.Status+" · round "+strconv.Itoa(p.Round)+"\n" }
 return out+"\nUse the Actions tab to create a workspace, submit a proposal, assign two reviewers, review, and finalize. Two approvals approve; two rejections reject; all other combinations request changes. The chair cannot override the rule.\n"
}

package taproom

// Leaderboards: net coins, sharpest guesses, longest streak, points and style. Stats are kept on
// each Player, and each board is a short sorted list of its top rows (boardTop), updated whenever
// a listed stat moves.

import (
	"strconv"
	"strings"
)

const (
	maxBoardRows = 50
	boardCount   = 5
)

// boards in display order: key, title, column heading.
var boards = [boardCount][3]string{
	{"points", "Points", "Lifetime points"},
	{"net", "Net coins", "Net GNOT"},
	{"sharp", "Sharpest guesses", "Avg distance"},
	{"streak", "Longest streak", "Weeks"},
	{"style", "Style", "Style score"},
}

type boardRow struct {
	addr address
	p    *Player
}

// styleOf sums rarity values of equipped items: common 1, rare 3, epic 6, legendary 10.
func styleOf(equipped [4]int) int64 {
	var s int64
	for _, id := range equipped {
		switch itemPrice(id) {
		case 40:
			s += 1
		case 150:
			s += 3
		case 400:
			s += 6
		case 1000:
			s += 10
		}
	}
	return s
}

// sharp100 is the average distance to the target in hundredths; -1 before any completed round.
func sharp100(p *Player) int64 {
	if p.Scored == 0 {
		return -1
	}
	return p.DistSum100 / p.Scored
}

// boardRank is one row of a board's top list: the player and the value they are ranked by.
type boardRank struct {
	Addr address
	V    int64
}

// boardTop holds each board's top maxBoardRows rows, best first. A short list instead of an index
// over every player: an update rewrites one list, which stops growing once it is full, so a
// player's first join adds little storage however many players there are. A listed player whose
// value drops out of the top rows leaves the list; a player just below returns when their own
// stats next change, so the rows near the bottom can lag until then.
var boardTop [boardCount][]boardRank

// boardValue is what a player is ranked by on board i. ok is false when the player is not listed:
// before their first Join, or on Sharpest guesses before a completed round.
func boardValue(i int, p *Player) (v int64, ok bool) {
	if !p.Joined {
		return 0, false
	}
	switch boards[i][0] {
	case "points":
		return p.Lifetime, true
	case "net":
		return p.Net, true
	case "sharp":
		if p.Scored == 0 {
			return 0, false
		}
		return sharp100(p), true
	case "streak":
		return p.BestStreak, true
	}
	return styleOf(p.Equipped), true
}

// ahead reports whether row x ranks above row y on board i: a better value (lower is better only
// for Sharpest guesses), then the lower address.
func ahead(i int, x, y boardRank) bool {
	if x.V != y.V {
		if boards[i][0] == "sharp" {
			return x.V < y.V
		}
		return x.V > y.V
	}
	return x.Addr < y.Addr
}

// reindex moves a player's rows on the boards after their stats change.
func reindex(a address) {
	p := getPlayer(a)
	for i := 0; i < boardCount; i++ {
		v, ok := boardValue(i, p)
		list := boardTop[i]
		pos := -1
		for j, r := range list {
			if r.Addr == a {
				pos = j
				break
			}
		}
		if pos >= 0 && ok && list[pos].V == v {
			continue // already listed at this value
		}
		changed := false
		if pos >= 0 {
			list = append(list[:pos], list[pos+1:]...)
			changed = true
		}
		if ok {
			row := boardRank{Addr: a, V: v}
			j := 0
			for j < len(list) && ahead(i, list[j], row) {
				j++
			}
			if j < maxBoardRows {
				list = append(list, boardRank{})
				copy(list[j+1:], list[j:])
				list[j] = row
				if len(list) > maxBoardRows {
					list = list[:maxBoardRows]
				}
				changed = true
			}
		}
		if changed {
			boardTop[i] = list
		}
	}
}

// board returns the top rows of a board, best first.
func board(name string, limit int) []boardRow {
	idx := -1
	for i, b := range boards {
		if b[0] == name {
			idx = i
		}
	}
	if idx < 0 {
		panic("unknown board: use points, net, sharp, streak or style")
	}
	if limit <= 0 || limit > maxBoardRows {
		limit = maxBoardRows
	}
	var rows []boardRow
	for _, r := range boardTop[idx] {
		if len(rows) >= limit {
			break
		}
		rows = append(rows, boardRow{addr: r.Addr, p: players.Get(r.Addr.String()).(*Player)})
	}
	return rows
}

// LeaderboardJSON returns the top rows (at most 50) of a board: points, net, sharp, streak or style.
// Each row carries every stat, so one call can fill any column.
func LeaderboardJSON(name string, limit int) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, r := range board(name, limit) {
		if i > 0 {
			sb.WriteString(",")
		}
		sharp := "null"
		if s := sharp100(r.p); s >= 0 {
			sharp = i64(s)
		}
		sb.WriteString(`{"rank":` + strconv.Itoa(i+1) + `,"addr":"` + r.addr.String() + `","points":` + i64(r.p.Lifetime))
		sb.WriteString(`,"net":` + i64(r.p.Net) + `,"wins":` + i64(r.p.Wins) + `,"sharp100":` + sharp)
		sb.WriteString(`,"bestStreak":` + i64(r.p.BestStreak) + `,"style":` + i64(styleOf(r.p.Equipped)) + `,"equipped":`)
		writeInts(&sb, r.p.Equipped[:])
		sb.WriteString("}")
	}
	sb.WriteString("]")
	return sb.String()
}

package taproom

// Render pages for gnoweb. Avatars are SVG data URIs from the avatar package, which gnoweb
// allows in markdown images. Paths: "" (home), "board/<name>", "player/<address>", "round/<id>".

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
)

// boardPageRows caps a board page: each avatar costs about 100M gas, and a Render query may use 3B.
const boardPageRows = 10

var rankNames = []string{"Newcomer", "Regular", "Sharp", "Oracle", "Legend"}
var rankAt = []int64{0, 100, 500, 1500, 4000}

func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case path == "":
		return renderHome()
	case len(parts) == 2 && parts[0] == "board":
		return renderBoard(parts[1])
	case len(parts) == 2 && parts[0] == "player":
		return renderPlayer(address(parts[1]))
	case len(parts) == 2 && parts[0] == "round":
		if id, err := strconv.Atoi(parts[1]); err == nil && id >= 0 && id < roundCount {
			return renderRound(getRound(id))
		}
	}
	return "# Not found\n\nNo such page. [Back to the taproom](" + link("") + ")\n"
}

func renderHome() string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Taproom\n\nA tavern of short mind games. Seal a number from 0 to 100; the pick closest to two thirds of the crowd's average takes the pot. 1 GNOT a seat, 0.5% to the tavern on completed rounds.\n\n")

	sb.WriteString("## Open tables\n\n")
	open := 0
	openRounds.ReverseIterate("", "", func(k string, _ any) bool {
		id, _ := strconv.Atoi(k)
		r := getRound(id)
		open++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " +
			strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + "\n")
		return open >= 10
	})
	if open == 0 {
		sb.WriteString("No open tables right now.\n")
	}

	sb.WriteString("\n## Recent results\n\n")
	shown := 0
	for i := len(recentSettled) - 1; i >= 0; i-- {
		r := getRound(recentSettled[i])
		shown++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " + resultLine(r) + "\n")
	}
	if shown == 0 {
		sb.WriteString("No settled rounds yet.\n")
	}

	sb.WriteString("\n## Leaderboards\n\n")
	writeBoardTable(&sb, "points", 5)
	sb.WriteString("\nAll boards:")
	for i, b := range boards {
		if i > 0 {
			sb.WriteString(" ·")
		}
		sb.WriteString(" [" + b[1] + "](" + link("board/"+b[0]) + ")")
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderBoard(name string) string {
	for _, b := range boards {
		if b[0] == name {
			var sb strings.Builder
			sb.WriteString("# " + b[1] + "\n\n")
			writeBoardTable(&sb, name, boardPageRows)
			sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
			return sb.String()
		}
	}
	// the name comes from the URL, so it is not echoed back into the page
	return "# Not found\n\nNo such board: use points, net, sharp, streak or style. [Back to the taproom](" + link("") + ")\n"
}

func writeBoardTable(sb *strings.Builder, name string, limit int) {
	var col string
	for _, b := range boards {
		if b[0] == name {
			col = b[2]
		}
	}
	rows := board(name, limit)
	if len(rows) == 0 {
		sb.WriteString("Nobody on this board yet.\n")
		return
	}
	sb.WriteString("| # | | Regular | " + col + " |\n|---|---|---|---|\n")
	for i, r := range rows {
		var v string
		switch name {
		case "points":
			v = i64(r.p.Lifetime)
		case "net":
			v = gnot(r.p.Net)
		case "sharp":
			v = hundredths(sharp100(r.p))
		case "streak":
			v = i64(r.p.BestStreak)
		case "style":
			v = i64(styleOf(r.p.Equipped))
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + gnome(r.addr, r.p.Equipped) + " | [" + short(r.addr) + "](" + link("player/"+r.addr.String()) + ") | " + v + " |\n")
	}
}

func renderPlayer(a address) string {
	v := players.Get(a.String())
	if v == nil {
		return "# Not found\n\nThis address has not played yet. [Back to the taproom](" + link("") + ")\n"
	}
	p := v.(*Player)
	rank := 0
	for i, at := range rankAt {
		if p.Lifetime >= at {
			rank = i
		}
	}
	var sb strings.Builder
	sb.WriteString("# Regular " + short(a) + "\n\n" + gnome(a, p.Equipped) + "\n\n")
	sb.WriteString("- Rank: " + rankNames[rank] + "\n")
	sb.WriteString("- Points: " + i64(p.Lifetime) + " lifetime, " + i64(p.Lifetime-p.Spent) + " to spend\n")
	sb.WriteString("- Weekly streak: " + i64(p.Streak) + " (best " + i64(p.BestStreak) + "), freezes held: " + strconv.Itoa(p.Freezes) + "\n")
	sb.WriteString("- Wins: " + i64(p.Wins) + "\n")
	sb.WriteString("- Net coins: " + gnot(p.Net) + "\n")
	if p.Scored > 0 {
		sb.WriteString("- Average distance to the target: " + hundredths(sharp100(p)) + " over " + i64(p.Scored) + plural(p.Scored, " round", " rounds") + "\n")
	}
	sb.WriteString("- Style score: " + i64(styleOf(p.Equipped)) + "\n\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

func renderRound(r *Round) string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Round " + strconv.Itoa(r.ID) + "\n\n")
	sb.WriteString(strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + ".\n\n")
	if r.Settled {
		sb.WriteString(resultLine(r) + "\n\n")
		if len(r.Winners) > 0 {
			sum, n := revealedSum(r)
			sb.WriteString("Target: " + hundredths(round2(r.Num*sum*100, r.Den*n)) + " (2/3 of the average " + hundredths(round2(sum*100, n)) + ")\n\n")
		}
	}
	sb.WriteString("| | Regular | Pick | Status |\n|---|---|---|---|\n")
	for _, p := range r.Seal.Players() {
		pick, status := "sealed", "sealed"
		if r.Seal.IsRevealed(p) {
			pick = i64(r.Seats[seatOf(r, p)].Pick)
			status = "revealed"
		}
		if r.Settled {
			switch {
			case isWinner(r, p):
				status = "winner"
			case len(r.Winners) == 0:
				status = "refunded"
			case status == "sealed":
				status = "forfeit"
				pick = "not revealed"
			}
		}
		var equipped [4]int
		if v := players.Get(p.String()); v != nil {
			equipped = v.(*Player).Equipped
		}
		sb.WriteString("| " + gnome(p, equipped) + " | [" + short(p) + "](" + link("player/"+p.String()) + ") | " + pick + " | " + status + " |\n")
	}
	sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

// ---------- helpers ----------

func phaseLine(r *Round, t int64) string {
	if r.Settled {
		return "settled"
	}
	switch {
	case t < r.Seal.CommitEnd:
		return "sealing until " + clock(r.Seal.CommitEnd)
	case t < r.Seal.RevealEnd:
		return "revealing until " + clock(r.Seal.RevealEnd)
	}
	return "ready to settle (anyone can settle)"
}

func resultLine(r *Round) string {
	if len(r.Winners) == 0 {
		return "cancelled, fewer than 2 revealed; everyone refunded, no fee"
	}
	var names []string
	for _, w := range r.Winners {
		names = append(names, "["+short(w)+"]("+link("player/"+w.String())+") with "+i64(r.Seats[seatOf(r, w)].Pick))
	}
	return "won by " + strings.Join(names, " and ") + ", pot " + gnot(r.Pot) + ", fee " + gnot(r.Fee)
}

func revealedSum(r *Round) (sum, n int64) {
	for _, o := range r.Seal.Revealed() {
		sum += r.Seats[seatOf(r, o.Who)].Pick
		n++
	}
	return sum, n
}

func isWinner(r *Round, a address) bool {
	for _, w := range r.Winners {
		if w == a {
			return true
		}
	}
	return false
}

func gnome(a address, equipped [4]int) string {
	return "![gnome](" + avatar.DataURI(a, equipped) + ")"
}

// link points at a page of this realm in gnoweb.
func link(sub string) string {
	p := "/" + strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land/")
	if sub == "" {
		return p
	}
	return p + ":" + sub
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// gnot formats ugnot as GNOT without trailing zeros: 2985000 -> "2.985 GNOT".
func gnot(u int64) string {
	sign := ""
	if u < 0 {
		sign, u = "-", -u
	}
	s := sign + i64(u/1000000)
	if frac := u % 1000000; frac != 0 {
		f := strconv.FormatInt(frac+1000000, 10)[1:]
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

// round2 divides num by den rounded to the nearest integer (both positive).
func round2(num, den int64) int64 {
	if den == 0 {
		return 0
	}
	return (num*10/den + 5) / 10
}

// hundredths formats 1778 as "17.78".
func hundredths(h int64) string {
	if h < 0 {
		return "-"
	}
	f := strconv.FormatInt(h%100+100, 10)[1:]
	return i64(h/100) + "." + f
}

func clock(ts int64) string {
	return time.Unix(ts, 0).UTC().Format("Jan 2 15:04 UTC")
}

func plural(n int64, one, many string) string {
	if n == 1 {
		return one
	}
	return many
}

package taproom

// Taproom realm: 2/3 Game round engine with stakes, permissionless settlement, pull payouts,
// and a time-window weekly streak. The commit-reveal lifecycle of each round (windows, sealed
// picks, reveals, who did not reveal) runs on the commitreveal package.

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/commitreveal/v0"
	"gno.land/p/nt/avl/v0"
)

const (
	denom       = "ugnot"
	weekSeconds = int64(604800)
	// Unix time zero fell on a Thursday; 4 days shifts week boundaries to Monday 00:00 UTC.
	weekOffset = int64(345600)

	pointsPlay = int64(10)
	pointsWin  = int64(30)
	streakStep = int64(4)
	streakCap  = int64(20)
	freezeCost = int64(40)
	maxFreezes = 2

	// Caps: players per round, open rounds per creator, window bounds.
	maxPlayers    = 10
	maxOpenRounds = 3
	minWindow     = int64(60)
	maxWindow     = int64(86400)

	// Cosmetic slots: hat, outfit, held item, companion (Player.Equipped order).
	slotCount = 4

	// Board skins: 0 = Oak table (free, owned by everyone), 1 = Moonlit, 2 = Gold-trim.
	skinCount = 3

	// Target fraction of the average: fixed at 2/3 in the MVP, stored per round.
	entryFee = int64(1000000) // 1 GNOT per seat

	// Salts shorter than this let anyone guess a pick from its hash (there are only 101 picks).
	minSaltLen = 16
	maxSaltLen = 128 // salts are kept and shown in RoundJSON, so they stay short and printable

	targetNum = int64(2)
	targetDen = int64(3)

	// Protocol fee in basis points (50 = 0.5%), taken from the pot of a completed round only.
	feeBps   = int64(50)
	bpsTotal = int64(10000)
)

// skinPrice is the points price per board skin ID; Oak (0) is free.
var skinPrice = []int64{0, 150, 400}

var (
	feeRecipient address // set once at deploy; can only withdraw accrued fees
	feesAccrued  int64
)

func init() {
	feeRecipient = unsafe.OriginCaller()
}

// nowOverride lets tests control time; zero means use the block time.
var nowOverride int64

// Seat is one player's place at a round, in join order (the order of Seal.Players()). A short list
// per round instead of trees keyed by address: a round has at most maxPlayers seats.
type Seat struct {
	Commit string // the hash sealed at Join; kept for RoundJSON so anyone can re-check the reveal
	Pick   int64  // set at Reveal
	Salt   string // public once revealed
	Bonus  int64  // streak bonus earned at reveal; paid only if the round completes
}

type Round struct {
	ID        int
	Creator   address
	Start     int64
	Seal      *commitreveal.Session // windows, commits, reveals and join order
	Seats     []Seat                // one per player, in join order
	Settled   bool
	Pot       int64
	Fee       int64
	Winners   []address
	BoardSkin int
	Num, Den  int64 // target fraction of the average; 2/3 in the MVP
}

type Player struct {
	Lifetime  int64
	Spent     int64
	HasPlayed bool
	LastWeek  int64
	Streak    int64
	Freezes   int
	Skins     []int  // owned board skins other than the free Oak table
	Owned     []int  // cosmetic item IDs
	Equipped  [4]int // item ID per slot (hat, outfit, held, companion); 0 = nothing

	// Leaderboard stats, updated at Join and Settle.
	Net        int64 // ugnot credited minus entry fees paid
	Wins       int64 // completed rounds won (a split win counts)
	Scored     int64 // revealed picks in completed rounds
	DistSum100 int64 // sum of distances to the target in those rounds, in hundredths
	BestStreak int64 // longest weekly streak reached

	Joined bool // has joined a round; only such players are listed on boards
}

var (
	roundTree     = avl.NewTree() // roundKey(id) -> *Round
	roundCount    int
	openRounds    = avl.NewTree() // roundKey(id) -> true while the round is not settled
	openByCreator = avl.NewTree() // address -> int, open rounds per creator (the 3-round cap)
	recentSettled []int           // the last 5 settled round IDs, oldest first
	players       = avl.NewTree() // address -> *Player
	claimable     = avl.NewTree() // address -> int64
)

// roundKey pads round IDs so the tree keeps them in numeric order.
func roundKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func openCount(a address) int {
	if v := openByCreator.Get(a.String()); v != nil {
		return v.(int)
	}
	return 0
}

// visibleASCII reports whether s has only printable ASCII characters other than space.
func visibleASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < 0x21 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

func now() int64 {
	if nowOverride != 0 {
		return nowOverride
	}
	return time.Now().Unix()
}

// weekIndex returns the Monday-00:00-UTC-aligned week number of a Unix timestamp.
func weekIndex(ts int64) int64 {
	d := ts - weekOffset
	w := d / weekSeconds
	if d%weekSeconds < 0 {
		w--
	}
	return w
}

// CommitHash is the value a player submits when joining round roundID:
// hex(sha256("<roundID>:<player address>:<pick>:<salt>")). Binding the round and the player means
// a hash copied from someone else's Join cannot be opened by the copier, nor reused in another round.
func CommitHash(roundID int, player address, pick int64, salt string) string {
	return commitreveal.Hash(sealedValue(roundID, player, pick), salt)
}

// sealedValue is what a round's Seal commits to for a player's pick.
func sealedValue(roundID int, player address, pick int64) string {
	return strconv.Itoa(roundID) + ":" + player.String() + ":" + strconv.FormatInt(pick, 10)
}

func mustUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call required")
	}
	return cur.Previous().Address()
}

func getRound(id int) *Round {
	if id < 0 || id >= roundCount {
		panic("unknown round")
	}
	return roundTree.Get(roundKey(id)).(*Round)
}

// seatOf returns the index of a's seat in r (join order), or -1.
func seatOf(r *Round, a address) int {
	for i, p := range r.Seal.Players() {
		if p == a {
			return i
		}
	}
	return -1
}

func getPlayer(a address) *Player {
	v := players.Get(a.String())
	if v == nil {
		p := &Player{}
		players.Set(a.String(), p)
		return p
	}
	return v.(*Player)
}

func credit(a address, amt int64) {
	cur := int64(0)
	if v := claimable.Get(a.String()); v != nil {
		cur = v.(int64)
	}
	claimable.Set(a.String(), cur+amt)
	getPlayer(a).Net += amt
}

// ownsSkin reports whether a may use a board skin: Oak (0) is free for everyone.
func ownsSkin(a address, skin int) bool {
	if skin == 0 {
		return true
	}
	v := players.Get(a.String())
	if v == nil {
		return false
	}
	for _, s := range v.(*Player).Skins {
		if s == skin {
			return true
		}
	}
	return false
}

// NewRound opens a round. commitSecs and revealSecs are window lengths in seconds.
// The creator must own boardSkin (Oak table, ID 0, is owned by everyone).
func NewRound(cur realm, commitSecs, revealSecs int64, boardSkin int) int {
	creator := mustUser(cur)
	if commitSecs < minWindow || revealSecs < minWindow || commitSecs > maxWindow || revealSecs > maxWindow {
		panic("windows must be 1 minute to 24 hours")
	}
	if boardSkin < 0 || boardSkin >= skinCount {
		panic("unknown board skin")
	}
	if !ownsSkin(creator, boardSkin) {
		panic("creator does not own this board skin")
	}
	open := openCount(creator)
	if open >= maxOpenRounds {
		panic("you already have 3 open rounds")
	}
	t := now()
	r := &Round{
		ID:        roundCount,
		Creator:   creator,
		Start:     t,
		Seal:      commitreveal.New(t, commitSecs, revealSecs),
		BoardSkin: boardSkin,
		Num:       targetNum,
		Den:       targetDen,
	}
	roundTree.Set(roundKey(r.ID), r)
	roundCount++
	openRounds.Set(roundKey(r.ID), true)
	openByCreator.Set(creator.String(), open+1)
	return r.ID
}

// Join deposits the entry fee and stores a hidden pick.
func Join(cur realm, roundID int, commit string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if r.Seal.Phase(t) != commitreveal.CommitPhase {
		panic("commit window closed")
	}
	if r.Seal.Has(caller) {
		panic("already joined")
	}
	if r.Seal.Count() >= maxPlayers {
		panic("round is full")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != entryFee {
		panic("must send exactly the entry fee in ugnot")
	}
	if err := r.Seal.Commit(t, caller, commit); err != nil {
		panic(err.Error())
	}
	r.Seats = append(r.Seats, Seat{Commit: commit})
	r.Pot += entryFee
	pl := getPlayer(caller)
	pl.Net -= entryFee
	pl.Joined = true
	reindex(caller)
}

// Reveal opens the pick; it must match the commit. It moves the streak (in block-time order)
// and records the bonus; points are paid at Settle, and only if the round completes.
func Reveal(cur realm, roundID int, pick int64, salt string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if pick < 0 || pick > 100 {
		panic("pick must be 0..100")
	}
	if len(salt) < minSaltLen || len(salt) > maxSaltLen || !visibleASCII(salt) {
		panic("salt must be 16 to 128 visible ASCII characters")
	}
	if err := r.Seal.Reveal(t, caller, sealedValue(roundID, caller, pick), salt); err != nil {
		panic(err.Error())
	}
	i := seatOf(r, caller)
	r.Seats[i].Pick, r.Seats[i].Salt, r.Seats[i].Bonus = pick, salt, updateStreak(caller, t)
	reindex(caller)
}

// Settle can be called by anyone once the reveal window has closed.
func Settle(cur realm, roundID int) {
	r := getRound(roundID)
	if now() < r.Seal.RevealEnd {
		panic("reveal window still open")
	}
	if r.Settled {
		panic("already settled")
	}
	r.Settled = true // effects before any payout bookkeeping
	openRounds.Remove(roundKey(r.ID))
	openByCreator.Set(r.Creator.String(), openCount(r.Creator)-1)
	recentSettled = append(recentSettled, r.ID)
	if len(recentSettled) > 5 {
		recentSettled = recentSettled[len(recentSettled)-5:]
	}
	defer func() { // board positions move with the credits and points below
		for _, p := range r.Seal.Players() {
			reindex(p)
		}
	}()

	var revealers []address
	var sum int64
	for _, o := range r.Seal.Revealed() { // join order
		revealers = append(revealers, o.Who)
		sum += r.Seats[seatOf(r, o.Who)].Pick
	}
	n := int64(len(revealers))

	// Fewer than two reveals: void round, everyone is refunded. No points.
	if n < 2 {
		for _, p := range r.Seal.Players() {
			credit(p, entryFee)
		}
		return
	}

	// Completed round: every revealer gets play points plus the bonus recorded at reveal.
	for _, p := range revealers {
		getPlayer(p).Lifetime += pointsPlay + r.Seats[seatOf(r, p)].Bonus
	}

	// Winner is closest to num/den of the average: minimise |den*n*pick - num*sum| (integer math).
	best := int64(-1)
	var winners []address
	for _, p := range revealers {
		d := r.Den*n*r.Seats[seatOf(r, p)].Pick - r.Num*sum
		if d < 0 {
			d = -d
		}
		// distance to the target = d / (den*n); kept in hundredths for the Sharpest guesses board
		pl := getPlayer(p)
		pl.Scored++
		pl.DistSum100 += (d*200 + r.Den*n) / (2 * r.Den * n) // rounded to the nearest hundredth
		if best < 0 || d < best {
			best = d
			winners = []address{p}
		} else if d == best {
			winners = append(winners, p)
		}
	}

	// Completed round (at least two reveals): take the fee, split the rest.
	fee := r.Pot * feeBps / bpsTotal
	r.Fee = fee
	feesAccrued += fee
	prize := r.Pot - fee

	count := int64(len(winners))
	share := prize / count
	rem := prize - share*count
	for i, w := range winners {
		amt := share
		if i == 0 {
			amt += rem
		}
		credit(w, amt)
		getPlayer(w).Lifetime += pointsWin - pointsPlay
		getPlayer(w).Wins++
	}
	r.Winners = winners
}

// Claim pays out the caller's balance (pull payment).
func Claim(cur realm) {
	caller := mustUser(cur)
	v := claimable.Get(caller.String())
	if v == nil || v.(int64) <= 0 {
		panic("nothing to claim")
	}
	amt := v.(int64)
	claimable.Set(caller.String(), int64(0)) // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// WithdrawFees sends accrued protocol fees to the fee recipient. It touches nothing else.
func WithdrawFees(cur realm) {
	caller := mustUser(cur)
	if caller != feeRecipient {
		panic("only the fee recipient can withdraw fees")
	}
	amt := feesAccrued
	if amt <= 0 {
		panic("no fees to withdraw")
	}
	feesAccrued = 0 // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// updateStreak moves the weekly streak for a play at ts and returns that play's bonus.
// Calls arrive in block-time order because Reveal calls it.
func updateStreak(a address, ts int64) int64 {
	p := getPlayer(a)
	w := weekIndex(ts)
	if !p.HasPlayed {
		p.Streak = 1
		p.LastWeek = w
	} else {
		g := w - p.LastWeek
		if g >= 1 {
			if p.Streak == 0 {
				// the streak was already reset for missed weeks: start again, keep any freezes
				p.Streak = 1
			} else if g == 1 {
				p.Streak++
			} else {
				missed := int(g - 1)
				if p.Freezes >= missed {
					p.Freezes -= missed
					p.Streak++
				} else {
					// not enough freezes: the streak resets and every held freeze is used up
					p.Streak = 1
					p.Freezes = 0
				}
			}
			p.LastWeek = w
		}
	}
	if p.Streak > p.BestStreak {
		p.BestStreak = p.Streak
	}
	p.HasPlayed = true
	bonus := streakStep * p.Streak
	if bonus > streakCap {
		bonus = streakCap
	}
	return bonus
}

// applyMissedWeeks spends freezes on weeks already missed before week w, as the next Reveal would.
// With too few freezes the streak drops to 0 and every freeze is used up; the next play starts week 1.
func applyMissedWeeks(p *Player, w int64) {
	if !p.HasPlayed || p.Streak == 0 {
		return
	}
	missed := int(w - p.LastWeek - 1)
	if missed <= 0 {
		return
	}
	if p.Freezes >= missed {
		p.Freezes -= missed
	} else {
		p.Streak = 0
		p.Freezes = 0
	}
	p.LastWeek = w - 1
}

// BuyFreeze spends points on a streak freeze (max 2 held). Weeks already missed are applied first,
// so a new freeze cannot cover a past week and a stale count cannot block the purchase.
func BuyFreeze(cur realm) {
	caller := mustUser(cur)
	p := getPlayer(caller)
	applyMissedWeeks(p, weekIndex(now()))
	if p.Freezes >= maxFreezes {
		panic("freeze limit reached")
	}
	if p.Lifetime-p.Spent < freezeCost {
		panic("not enough points")
	}
	p.Spent += freezeCost
	p.Freezes++
}

// BuySkin spends points on a board skin (Moonlit or Gold-trim). Oak is free and always owned.
func BuySkin(cur realm, skin int) {
	caller := mustUser(cur)
	if skin <= 0 || skin >= skinCount {
		panic("unknown or free board skin")
	}
	if ownsSkin(caller, skin) {
		panic("skin already owned")
	}
	p := getPlayer(caller)
	price := skinPrice[skin]
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Skins = append(p.Skins, skin)
}

// itemPrice returns the points price of a cosmetic item, or -1 for an unknown ID.
// itemID = slotBase + n with slotBase 100 hat, 200 outfit, 300 held, 400 companion and n = 1..12.
// Rarity by n: 1, 5, 6 common 40; 2, 7, 8 rare 150; 3, 9, 10 epic 400; 4, 11, 12 legendary 1000.
func itemPrice(id int) int64 {
	slot, n := id/100, id%100
	if slot < 1 || slot > slotCount || n < 1 || n > 12 {
		return -1
	}
	switch n {
	case 1, 5, 6:
		return 40
	case 2, 7, 8:
		return 150
	case 3, 9, 10:
		return 400
	}
	return 1000
}

func ownsItem(p *Player, id int) bool {
	for _, o := range p.Owned {
		if o == id {
			return true
		}
	}
	return false
}

// BuyItem spends points on a cosmetic item. Items cannot be traded and never affect outcomes.
func BuyItem(cur realm, itemID int) {
	caller := mustUser(cur)
	price := itemPrice(itemID)
	if price < 0 {
		panic("unknown item")
	}
	p := getPlayer(caller)
	if ownsItem(p, itemID) {
		panic("item already owned")
	}
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Owned = append(p.Owned, itemID)
}

// Equip wears an owned item in its slot (0 hat, 1 outfit, 2 held, 3 companion); itemID 0 takes it off.
func Equip(cur realm, slot int, itemID int) {
	caller := mustUser(cur)
	if slot < 0 || slot >= slotCount {
		panic("unknown slot")
	}
	p := getPlayer(caller)
	if itemID != 0 {
		if !ownsItem(p, itemID) {
			panic("item not owned")
		}
		if itemID/100 != slot+1 {
			panic("item does not fit this slot")
		}
	}
	p.Equipped[slot] = itemID
	reindex(caller)
}

// Views (non-crossing)

func OwnsSkin(a address, skin int) bool { return ownsSkin(a, skin) }

func Claimable(a address) int64 {
	if v := claimable.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func PlayerStats(a address) (lifetime, spendable, streak int64, freezes int) {
	v := players.Get(a.String())
	if v == nil {
		return 0, 0, 0, 0
	}
	p := v.(*Player)
	return p.Lifetime, p.Lifetime - p.Spent, p.Streak, p.Freezes
}

package taproom

// Read-only views for the web UI, returned as compact JSON strings so a client can read them
// with one vm/qeval call. Addresses are bech32 and numbers are plain integers, so no escaping is needed.

import (
	"strconv"
	"strings"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
)

func RoundCount() int { return roundCount }

// AvatarSVG draws a player's gnome wearing their equipped items (see the avatar package).
func AvatarSVG(a address) string {
	var equipped [4]int
	if v := players.Get(a.String()); v != nil {
		equipped = v.(*Player).Equipped
	}
	return avatar.Render(a, equipped)
}

func FeeRecipient() address { return feeRecipient }

func FeesAccrued() int64 { return feesAccrued }

// RoundsJSON returns rounds [offset, offset+limit) as a JSON array (limit capped at 100).
func RoundsJSON(offset, limit int) string {
	if limit > 100 {
		limit = 100
	}
	var sb strings.Builder
	sb.WriteString("[")
	for i := offset; i >= 0 && i < roundCount && i < offset+limit; i++ {
		if i > offset {
			sb.WriteString(",")
		}
		writeRound(&sb, getRound(i))
	}
	sb.WriteString("]")
	return sb.String()
}

func RoundJSON(id int) string {
	var sb strings.Builder
	writeRound(&sb, getRound(id))
	return sb.String()
}

// PlayerJSON reports a player as the next Reveal would see them: weeks already missed are applied
// to a copy (freezes spent, or the streak shown as 0). It never changes state.
func PlayerJSON(a address) string {
	p := Player{}
	if v := players.Get(a.String()); v != nil {
		p = *v.(*Player)
	}
	applyMissedWeeks(&p, weekIndex(now()))

	var sb strings.Builder
	sb.WriteString(`{"addr":"` + a.String() + `","lifetime":` + i64(p.Lifetime) + `,"spent":` + i64(p.Spent))
	sb.WriteString(`,"streak":` + i64(p.Streak) + `,"lastWeek":`)
	if p.HasPlayed {
		sb.WriteString(i64(p.LastWeek))
	} else {
		sb.WriteString("null")
	}
	sb.WriteString(`,"freezes":` + strconv.Itoa(p.Freezes) + `,"owned":`)
	writeInts(&sb, p.Owned)
	sb.WriteString(`,"equipped":`)
	writeInts(&sb, p.Equipped[:])
	sb.WriteString(`,"skins":`)
	writeInts(&sb, append([]int{0}, p.Skins...))
	sb.WriteString(`,"claimable":` + i64(Claimable(a)) + "}")
	return sb.String()
}

func writeRound(sb *strings.Builder, r *Round) {
	sb.WriteString(`{"id":` + strconv.Itoa(r.ID) + `,"creator":"` + r.Creator.String() + `","skin":` + strconv.Itoa(r.BoardSkin))
	sb.WriteString(`,"start":` + i64(r.Start) + `,"commitEnd":` + i64(r.Seal.CommitEnd) + `,"revealEnd":` + i64(r.Seal.RevealEnd))
	sb.WriteString(`,"num":` + i64(r.Num) + `,"den":` + i64(r.Den) + `,"settled":` + strconv.FormatBool(r.Settled))
	sb.WriteString(`,"pot":` + i64(r.Pot) + `,"fee":` + i64(r.Fee) + `,"winners":[`)
	for i, w := range r.Winners {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"` + w.String() + `"`)
	}
	sb.WriteString(`],"entries":[`)
	for i, p := range r.Seal.Players() {
		if i > 0 {
			sb.WriteString(",")
		}
		// a pick and its salt stay hidden until their owner reveals them
		s := r.Seats[i]
		revealed := r.Seal.IsRevealed(p)
		pick, salt, bonus := "null", "null", int64(0)
		if revealed {
			pick, salt, bonus = i64(s.Pick), strconv.Quote(s.Salt), s.Bonus
		}
		sb.WriteString(`{"addr":"` + p.String() + `","commit":"` + s.Commit + `","revealed":` + strconv.FormatBool(revealed))
		sb.WriteString(`,"pick":` + pick + `,"salt":` + salt + `,"bonus":` + i64(bonus) + "}")
	}
	sb.WriteString("]}")
}

func writeInts(sb *strings.Builder, xs []int) {
	sb.WriteString("[")
	for i, x := range xs {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Itoa(x))
	}
	sb.WriteString("]")
}

func i64(x int64) string { return strconv.FormatInt(x, 10) }
